    return {"messages": [rejection_message(call)]}

RISKY = {"issue_refund", "cancel_order"}

def router(state: AgentState) -> Command[Literal["approval", "tools", "__end__"]]:
    calls = state["messages"][-1].tool_calls
    if not calls:
        return Command(goto=END)
    if any(c["name"] in RISKY for c in calls):
        return Command(goto="approval", update={"pending_risky": True})
    return Command(goto="tools")

